class ScreenBarSettingsTakeEffectImmediatelyTests(unittest.TestCase):
    """Regression guard: toggling a Screen Bar geometry/drawing setting
    (Alcove compatibility, wraps-menu-bar) must reposition the Screen Bar
    right away. Before this fix, both settings were only ever re-read the
    next time sync_virtual_status_device happened to run -- which, with a
    physical device connected, only happens on a genuine LED write. Once
    agent layout stopped thrashing (see the ordering-stability fix), that
    could be a very long wait: the setting would visibly "not work" even
    though it saved correctly."""

    def setUp(self) -> None:
        isolate_controller(self)
        # The bug only manifests once the Screen Bar window already exists
        # (reposition() is a no-op before that) -- matches the real
        # scenario: the user already has it visible and flips a setting.
        self.controller.virtual_status_device.show()

    def test_toggling_wraps_menu_bar_repositions_without_any_led_write(self) -> None:
        before = self.controller.virtual_status_device.window.frame().size.width
        checkbox = self.status_bar.NSButton.alloc().init()
        self.status_bar.set_checkbox_state(checkbox, True)
        with patch.object(self.status_bar.StatusBarController, "sync_leds") as sync_leds:
            self.controller.toggleScreenBarWrapsMenuBar_(checkbox)
            sync_leds.assert_not_called()
        after = self.controller.virtual_status_device.window.frame().size.width
        self.assertTrue(self.controller.settings.virtual_status_device_wraps_menu_bar)
        self.assertTrue(self.controller.virtual_status_device.wraps_menu_bar)
        self.assertGreaterEqual(after, before)

    def test_settings_round_trip_persists_colors(self) -> None:
        settings = AgentMonitorSettings().with_colors(
            ColorSettings.defaults().with_agent_color("codex", "#123456")
        )

        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(settings, path)
            loaded = load_settings(path)

        self.assertEqual(loaded.colors.agent_color("codex"), "#123456")

    def test_corrupt_colors_block_falls_back_without_breaking_other_settings(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(
                AgentMonitorSettings().with_setup_screen_completed(True),
                path,
            )
            data = json.loads(path.read_text())
            data["colors"] = "not-a-dict"
            data["closed_lid_animation"] = 12345
            path.write_text(json.dumps(data))

            loaded = load_settings(path)

        self.assertEqual(loaded.colors.to_dict(), ColorSettings.defaults().to_dict())
        self.assertTrue(loaded.setup_screen_completed)


class TranscriptFallbackTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)

    def test_transcript_monitor_follows_the_switches(self) -> None:
        # The "Watch ... transcripts" switches used to save a setting
        # nothing in the app read (transcript scanning lived only in the
        # CLI's monitor) -- the fallback silently did nothing.
        from sidepulse.collector import CODEX_TRANSCRIPT_PROVIDER

        self.controller.settings = (
            self.controller.settings.with_transcript_provider("codex", False)
            .with_transcript_provider("claude", False)
        )
        self.assertIsNone(self.controller.build_transcript_monitor())

        self.controller.settings = self.controller.settings.with_transcript_provider(
            "codex", True
        )
        monitor = self.controller.build_transcript_monitor()
        self.assertIsNotNone(monitor)
        self.assertEqual(
            {source.provider for source in monitor.sources},
            {CODEX_TRANSCRIPT_PROVIDER},
        )

    def test_transcript_records_reach_the_live_monitor_exactly_once(self) -> None:
        from sidepulse.models import HookEvent

        # Relative, not a wall-clock date: a hardcoded timestamp aged
        # past the collector's staleness window overnight and the test
        # started failing on the calendar, not on a regression.
        record = HookEvent(
            provider="codex",
            logged_at=datetime.now(timezone.utc) - timedelta(minutes=1),
            event_name="SessionStart",
            raw={},
            session_id="transcript-session",
        )

        class FakeTranscriptMonitor:
            def __init__(self, records):
                self.records = records
                self.calls = 0

            def iter_records(self):
                self.calls += 1
                return list(self.records)

        fake = FakeTranscriptMonitor([record])
        self.controller.transcript_monitor = fake
        self.controller.transcript_watermark = None

        # Transcript discovery runs off-main in production; a synchronous
        # stand-in delivers the batch inline so ingestion is observable
        # without pumping a run loop. The dedupe/watermark logic under test
        # still runs in applyTranscriptFallbackBatch_.
        from sidepulse.transcript_runtime import TranscriptFallbackBatch

        controller = self.controller

        class _SyncTranscriptService:
            def __init__(self):
                self._generation = 0

            def request(self, monitor, *, known_signature, callback):
                self._generation += 1
                records = tuple(monitor.iter_records())
                controller.applyTranscriptFallbackBatch_(
                    TranscriptFallbackBatch(
                        self._generation,
                        id(monitor),
                        object(),
                        records,
                    )
                )
                return self._generation

            def close(self):
                return None

        self.controller._production_transcript_service = _SyncTranscriptService()

        self.controller.ingest_transcript_fallback()
        first_keys = set(self.controller.monitor.statuses_by_key)
        self.assertTrue(
            any("transcript-session" in key for key in first_keys),
            f"transcript record never reached the live monitor: {first_keys}",
        )
        # Watermark: the same records must not re-ingest on later ticks.
        before = dict(self.controller.monitor.statuses_by_key)
        self.controller.ingest_transcript_fallback()
        self.assertEqual(self.controller.monitor.statuses_by_key, before)
        self.assertEqual(fake.calls, 2)

    def test_typed_hook_hint_reconciles_the_persisted_source_then_refreshes(self) -> None:
        hint = ProviderRefreshHint(
            SourceKey("codex", "hooks", "global", "live_agent_events"),
            EventToken("event:typed-live-update"),
        )
        log_path = Path("/private/sidepulse/codex.jsonl")

        with (
            patch(
                "sidepulse.status_bar.detect_log_path",
                return_value=log_path,
            ),
            patch.object(
                self.controller.monitor,
                "reconcile_refresh_hint",
            ) as reconcile,
            patch.object(self.controller, "schedule_event_refresh") as schedule,
        ):
            self.controller.handle_hook_event_message(hint)

        reconcile.assert_called_once_with(hint, log_path=log_path)
        schedule.assert_called_once_with()


class SignalEngineTests(unittest.TestCase):
    def test_default_styles_render_the_pre_engine_programs_byte_for_byte(self) -> None:
        # The migration to the Signal Engine had to be INVISIBLE: the
        # default styles reproduce the old bespoke programs exactly.
        #
        # One exception, taken deliberately in Wave 7. The notification
        # blink kept its 170/130ms cadence but lost `cosine`, because a
        # cosine blink is a triangle and a triangle is what `breathe`
        # already is -- measured through the firmware, "blink" was a second
        # name for "breathe" at another ratio. The DURATIONS are still the
        # pre-engine ones; only the easing moved, and it moved to the shape
        # the pattern is named after. The low-battery and calendar
        # breathes below are untouched, which is what still makes this a
        # migration test rather than a changelog.
        from sidepulse import signals
        from sidepulse.led_status import style_to_program

        self.assertEqual(
            style_to_program(signals.DEFAULT_SIGNAL_STYLES[signals.SIGNAL_LOW_BATTERY]),
            "off 400ms cosine\n#E01010 3600ms pulse\nrepeat",
        )
        self.assertEqual(
            style_to_program(signals.DEFAULT_SIGNAL_STYLES[signals.SIGNAL_CALENDAR]),
            "off 400ms cosine\n#A45CFF 2600ms pulse\nrepeat",
        )
        self.assertEqual(
            style_to_program(
                signals.DEFAULT_SIGNAL_STYLES[signals.SIGNAL_NOTIFICATION],
                color="#34C759",
            ),
            "\n".join(["#34C759 170ms none\noff 130ms none"] * 3),
        )

    def test_every_pattern_stays_within_device_limits_at_every_extreme(self) -> None:
        import re as _re

        from sidepulse import signals
        from sidepulse.device_writer import MAX_LED_BYTES, MAX_LED_LINES
        from sidepulse.led_status import style_to_program

        for pattern in signals.SIGNAL_PATTERNS:
            for speed in (signals.MIN_SPEED_SECONDS, 1.0, signals.MAX_SPEED_SECONDS):
                for intensity in (signals.MIN_INTENSITY, 1.0):
                    style = signals.SignalStyle("#ABCDEF", pattern, speed, intensity)
                    program = style_to_program(style, 128, led_count=8)
                    label = f"{pattern}@{speed}s/{intensity}"
                    self.assertLessEqual(len(program.encode()), MAX_LED_BYTES, label)
                    self.assertLessEqual(len(program.splitlines()), MAX_LED_LINES, label)
                    for value in _re.findall(r"(\d+)ms", program):
                        self.assertLessEqual(int(value), 65535, label)

    def test_signal_style_settings_round_trip_and_validation(self) -> None:
        from sidepulse import signals

        style = signals.SignalStyle("#112233", signals.PATTERN_SWEEP, 2.0, 0.6)
        configured = AgentMonitorSettings().with_signal_style("calendar", style)
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured, path)
            reloaded = load_settings(path)
        self.assertEqual(reloaded.signal_style("calendar"), style)
        # Untouched signals keep their defaults.
        self.assertEqual(
            reloaded.signal_style("low_battery"),
            signals.DEFAULT_SIGNAL_STYLES["low_battery"],
        )
        # A hand-edited bad pattern falls back to the default, never crashes.
        broken = dict(configured.to_dict())
        broken["signal_styles"] = {"calendar": {"pattern": "explode", "speed_seconds": 99}}
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            path.write_text(json.dumps(broken))
            reloaded = load_settings(path)
        style = reloaded.signal_style("calendar")
        self.assertIn(style.pattern, signals.SIGNAL_PATTERNS)
        self.assertLessEqual(style.speed_seconds, signals.MAX_SPEED_SECONDS)

    def test_unknown_signal_key_is_rejected(self) -> None:
        from sidepulse import signals

        with self.assertRaises(ValueError):
            AgentMonitorSettings().with_signal_style(
                "nope", signals.DEFAULT_SIGNAL_STYLES["calendar"]
            )


class SignalStyleCardTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)
        self.controller.show_settings_window()
        self.controller.ensure_all_settings_panes()

    def test_every_signal_gets_a_full_style_card(self) -> None:
        from sidepulse import signals

        for key, _title, show_color in self.status_bar.SIGNAL_STYLE_CARDS:
            thumbs = self.controller.settings_fields.get(f"signal_thumbs:{key}")
            self.assertIsInstance(thumbs, dict, key)
            expected = set(signals.SIGNAL_PATTERNS)
            if key in signals.CONTINUOUS_SIGNALS:
                # One-shot patterns would flash once then leave the bar
                # dark for the rest of a held condition -- not offered.
                expected -= set(signals.ONE_SHOT_PATTERNS)
            self.assertEqual(set(thumbs), expected, key)
            self.assertIsNotNone(self.controller.settings_fields.get(f"signal_preview:{key}"))
            self.assertIsNotNone(self.controller.settings_fields.get(f"signal_speed:{key}"))
            self.assertIsNotNone(self.controller.settings_fields.get(f"signal_intensity:{key}"))
            if show_color:
                self.assertIsNotNone(self.controller.settings_fields.get(f"signal_color:{key}"))
            else:
                self.assertIsNone(self.controller.settings_fields.get(f"signal_color:{key}"))

