class IdentityColorTests(unittest.TestCase):
    def test_assignment_is_deterministic_and_collision_free(self) -> None:
        from sidepulse.colors import IDENTITY_PALETTE, identity_colors_for_agents

        ids = [f"agent-{index}" for index in range(8)]
        first = identity_colors_for_agents(ids)
        second = identity_colors_for_agents(ids)
        self.assertEqual(first, second)
        # Eight sessions -> eight DISTINCT hues.
        self.assertEqual(len(set(first.values())), 8)
        for color in first.values():
            self.assertIn(color, IDENTITY_PALETTE)
        # A stable subset keeps its colors when others leave... for ids
        # whose preferred slots never collided.
        alone = identity_colors_for_agents([ids[0]])
        self.assertEqual(alone[ids[0]], first[ids[0]])

    def test_identity_palette_stays_clear_of_state_hues(self) -> None:
        from sidepulse.colors import IDENTITY_PALETTE

        for reserved in ("#00E5FF", "#00FF66", "#FF3A00", "#A45CFF", "#E01010"):
            self.assertNotIn(reserved, IDENTITY_PALETTE)

    def test_multiple_sessions_get_identity_colors_single_keeps_brand(self) -> None:
        """A crowd is told apart WITHOUT anyone losing their brand.

        This used to assert every crowd member wore an IDENTITY_PALETTE
        slot -- eight hues chosen for mutual distinctness and nothing
        else. That is exactly the reported defect: with two sessions up,
        Claude rendered magenta #E44CFF and its declared terracotta
        #D97757 appeared nowhere. Distinctness is still required below;
        it is now bought with lightness inside each brand's own hue.
        """
        from sidepulse.colors import ColorSettings, _active_agents

        one = (_status("codex", AgentMode.WORKING),)
        two = (
            _status("codex", AgentMode.WORKING),
            _status("claude", AgentMode.WORKING),
        )
        settings = ColorSettings.defaults()
        solo = _active_agents(one, settings)
        self.assertEqual(solo[0].color, settings.agent_color("codex"))
        crowd = _active_agents(two, settings)
        self.assertEqual(len({agent.color for agent in crowd}), 2)
        by_provider = {agent.provider: agent.color for agent in crowd}
        self.assertEqual(by_provider["codex"], settings.agent_color("codex"))
        self.assertEqual(by_provider["claude"], settings.agent_color("claude"))

    def test_two_sessions_of_one_provider_stay_inside_that_brands_hue(self) -> None:
        """Which product, then which session -- in that order."""
        from dataclasses import replace as dataclass_replace

        from sidepulse.colors import ColorSettings, _active_agents, hex_to_oklch

        settings = ColorSettings.defaults()
        base = _status("claude", AgentMode.WORKING)
        crowd = _active_agents(
            (
                dataclass_replace(base, agent_id="claude:session:a"),
                dataclass_replace(base, agent_id="claude:session:b"),
            ),
            settings,
        )

        self.assertEqual(len({agent.color for agent in crowd}), 2)
        brand_hue = hex_to_oklch(settings.agent_color("claude"))[2]
        for agent in crowd:
            self.assertAlmostEqual(hex_to_oklch(agent.color)[2], brand_hue, delta=6.0)

    def test_session_override_wins_and_round_trips(self) -> None:
        from sidepulse.colors import ColorSettings, _active_agents

        two = (
            _status("codex", AgentMode.WORKING),
            _status("claude", AgentMode.WORKING),
        )
        agent_id = two[0].agent_id
        settings = ColorSettings.defaults().with_session_color(agent_id, "112233")
        crowd = _active_agents(two, settings)
        colors = [agent.color for agent in crowd]
        self.assertIn("#112233", colors)
        reloaded = ColorSettings.from_dict(settings.to_dict())
        self.assertEqual(reloaded.session_color(agent_id), "#112233")
        cleared = reloaded.with_session_color(agent_id, None)
        self.assertIsNone(cleared.session_color(agent_id))


class EscalationTests(unittest.TestCase):
    def test_stage_function_thresholds_and_tier_ceiling(self) -> None:
        from sidepulse import signals

        def stage(elapsed, tier="takeover"):
            return signals.escalation_stage(
                elapsed,
                ramp_seconds=30.0,
                menu_bar_seconds=120.0,
                final_seconds=300.0,
                tier=tier,
            )

        self.assertEqual(stage(None), 0)
        self.assertEqual(stage(10.0), 0)
        self.assertEqual(stage(30.0), 1)
        self.assertEqual(stage(119.9), 1)
        self.assertEqual(stage(120.0), 2)
        self.assertEqual(stage(300.0), 3)
        # The tier is a CEILING: quieter tiers never reach later stages.
        self.assertEqual(stage(300.0, tier="light"), 1)
        self.assertEqual(stage(300.0, tier="menu_bar"), 2)
        self.assertEqual(stage(300.0, tier="chime"), 3)

    def test_escalation_settings_round_trip_and_ordering(self) -> None:
        configured = (
            AgentMonitorSettings()
            .with_escalation_tier("chime")
            .with_escalation_thresholds(ramp_seconds=60, menu_bar_seconds=45, final_seconds=10)
        )
        # Thresholds can never be out of order: each floor is the prior.
        self.assertEqual(configured.escalation_ramp_seconds, 60.0)
        self.assertGreaterEqual(configured.escalation_menu_bar_seconds, 60.0)
        self.assertGreaterEqual(
            configured.escalation_final_seconds, configured.escalation_menu_bar_seconds
        )
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured, path)
            reloaded = load_settings(path)
        self.assertEqual(reloaded.escalation_tier, "chime")
        with self.assertRaises(ValueError):
            AgentMonitorSettings().with_escalation_tier("shout")


class EscalationControllerTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)

    def test_soft_asks_never_escalate(self) -> None:
        # A finished turn that merely ENDED with a question must not ramp
        # toward a chime -- only tracked live requests (PermissionRequest
        # and actionable notifications) escalate.
        soft = (_status("codex", AgentMode.WAITING_FOR_INPUT, event_name="Stop"),)
        self.controller.track_ask_blocked(soft)
        self.assertIsNone(self.controller.ask_blocked_since)

    def test_blocked_episode_tracking_keeps_stage_two_static_and_nonblank(self) -> None:
        asking = (_status("codex", AgentMode.WAITING_FOR_INPUT),)
        self.controller.track_ask_blocked(asking)
        self.assertIsNotNone(self.controller.ask_blocked_since)
        # A terminal failure ends the live-request episode.
        self.controller.track_ask_blocked((_status("codex", AgentMode.BLOCKED_ERROR),))
        self.assertIsNone(self.controller.ask_blocked_since)

        # Age the episode past stage 2: attention stays semantic and static.
        self.controller.ask_blocked_by_agent = {"codex": time.monotonic() - 200.0}
        self.controller.ask_blocked_since = time.monotonic() - 200.0
        self.controller.status_item = MagicMock()
        button = self.controller.status_item.button.return_value
        with patch.object(self.status_bar, "NSTimer") as timer_api:
            self.controller.apply_escalation()
        self.assertGreaterEqual(self.controller.current_escalation_stage(), 2)
        timer_api.scheduledTimerWithTimeInterval_target_selector_userInfo_repeats_.assert_not_called()
        self.assertNotIn(call(""), button.setTitle_.call_args_list)
        self.assertFalse(hasattr(self.controller, "escalationFlashTick_"))

        # Any non-ask state ends the episode without a blank intermediate frame.
        self.controller.track_ask_blocked((_status("codex", AgentMode.WORKING),))
        self.assertIsNone(self.controller.ask_blocked_since)
        self.assertNotIn(call(""), button.setTitle_.call_args_list)

    def test_escalation_follows_the_oldest_current_ask_per_agent(self) -> None:
        # Agent A blocked for ages, agent B just asked; answering A must
        # drop escalation to B's fresh episode, not inherit A's stage.
        now = time.monotonic()
        a_ask = _status("codex", AgentMode.WAITING_FOR_INPUT)
        b_ask = _status("claude", AgentMode.WAITING_FOR_INPUT)
        self.controller.ask_blocked_by_agent = {}
        self.controller.track_ask_blocked((a_ask, b_ask))
        self.controller.ask_blocked_by_agent["codex"] = now - 400.0
        self.controller.track_ask_blocked((a_ask, b_ask))
        self.assertLessEqual(self.controller.ask_blocked_since, now - 399.0)
        # A answered: only B's young episode remains.
        self.controller.track_ask_blocked((b_ask,))
        self.assertGreater(self.controller.ask_blocked_since, now - 10.0)
        self.assertEqual(self.controller.current_escalation_stage(), 0)

    def test_takeover_claims_the_top_of_the_precedence_order(self) -> None:
        device = self.status_bar.StatusBarDevice(
            device_id="SidePulsePro",
            name="SidePulse Pro",
            root=Path("/Volumes/SidePulsePro"),
            target=Path("/Volumes/SidePulsePro/LEDS.LED"),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
        )
        self.controller.settings = self.controller.settings.with_escalation_tier("takeover")
        self.controller.ask_blocked_since = time.monotonic() - 400.0
        self.assertEqual(
            self.controller.active_led_display_kind_for_device(device, None),
            self.status_bar.LED_DISPLAY_ESCALATION,
        )
        program = self.controller.escalation_takeover_program(255)
        self.assertIn("repeat", program)

    def test_ramp_boosts_effective_brightness(self) -> None:
        device = self.status_bar.StatusBarDevice(
            device_id="SidePulsePro",
            name="SidePulse Pro",
            root=Path("/Volumes/SidePulsePro"),
            target=Path("/Volumes/SidePulsePro/LEDS.LED"),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
        )
        object.__setattr__(device, "brightness", 100) if hasattr(device, "__dataclass_fields__") else None
        baseline = self.controller.effective_brightness_for_device(device)
        self.controller.ask_blocked_since = time.monotonic() - 60.0
        boosted = self.controller.effective_brightness_for_device(device)
        self.assertGreater(boosted, baseline * 1.05)


class HardeningTests(unittest.TestCase):
    def test_charging_program_repeats(self) -> None:
        # Without repeat the charge pulse played once per device write
        # and froze until the next 15s sync -- four blinks a minute.
        from sidepulse.battery import BatterySnapshot, program_for_battery

        snapshot = BatterySnapshot(
            percent=50, is_plugged=True, is_charging=True, battery_present=True, adapter_watts=60
        )
        program = program_for_battery(snapshot, led_count=8)
        self.assertIn("pulse", program)
        self.assertIn("repeat", program)

    def test_trim_oversized_logs_keeps_the_tail_only(self) -> None:
        from sidepulse import audit

        with tempfile.TemporaryDirectory() as tmp:
            state = Path(tmp)
            big = state / "hooks" / "codex.jsonl"
            big.parent.mkdir(parents=True)
            line = json.dumps({"event": "x", "pad": "y" * 200}) + "\n"
            count = (audit.TRIM_THRESHOLD_BYTES // len(line)) + 100
            big.write_text(line * count)
            small = state / "tiny.jsonl"
            small.write_text(line * 3)
            trimmed = audit.trim_oversized_logs(state)
            self.assertEqual(trimmed, 1)
            self.assertEqual(len(big.read_text().splitlines()), audit.TRIM_KEEP_LINES)
            self.assertEqual(len(small.read_text().splitlines()), 3)


class PrivateStateSecurityTests(unittest.TestCase):
    @staticmethod
    def _mode(path: Path) -> int:
        import stat

        return stat.S_IMODE(path.lstat().st_mode)

    def test_audit_omits_prompt_fallback_and_raw_event_copy(self) -> None:
        from sidepulse.audit import status_audit_record

        prompt_event = parse_log_line(
            "claude",
            json.dumps(
                {
                    "hook_event_name": "UserPromptSubmit",
                    "session_id": "private-session",
                    "prompt": "private prompt body",
                    "authorization": "Bearer private-token",
                    "logged_at": "2026-08-12T12:00:00Z",
                }
            ),
        )
        self.assertIsNotNone(prompt_event)
        prompt_record = status_audit_record(prompt_event, None)
        self.assertEqual(prompt_record["message"], "")
        self.assertEqual(prompt_record["raw_preview"], "")

        notification = parse_log_line(
            "claude",
            json.dumps(
                {
                    "hook_event_name": "Notification",
                    "session_id": "ask-session",
                    "notification_type": "idle_prompt",
                    "message": "Claude is waiting for your input",
                    "logged_at": "2026-08-12T12:01:00Z",
                }
            ),
        )
        self.assertIsNotNone(notification)
        notification_record = status_audit_record(notification, None)
        self.assertEqual(
            notification_record["message"],
            "Claude is waiting for your input",
        )
        self.assertEqual(notification_record["raw_preview"], "")

        assistant_body = parse_log_line(
            "claude",
            json.dumps(
                {
                    "hook_event_name": "Stop",
                    "session_id": "completion-session",
                    "last_assistant_message": "private assistant response",
                    "logged_at": "2026-08-12T12:02:00Z",
                }
            ),
        )
        self.assertIsNotNone(assistant_body)
        assistant_record = status_audit_record(assistant_body, None)
        self.assertEqual(assistant_record["message"], "")
        self.assertEqual(assistant_record["raw_preview"], "")

    def test_sensitive_entrypoints_create_owner_only_files(self) -> None:
        from sidepulse import usage_stats

        with tempfile.TemporaryDirectory() as tmp:
            base = Path(tmp)
            previous = os.umask(0)
            try:
                settings_path = base / "settings" / "settings.json"
                save_settings(
                    AgentMonitorSettings().with_escalation_webhook_url(
                        "https://private.example/hook"
                    ),
                    settings_path,
                )

                hook_path = base / "hooks" / "codex.jsonl"
                write_hook_payload(
                    "codex",
                    hook_path,
                    json.dumps(
                        {
                            "hook_event_name": "Stop",
                            "session_id": "codex-session",
                            "last_assistant_message": "private response",
                            "authorization": "Bearer private-token",
                        }
                    ),
                )
                hook_obj = json.loads(hook_path.read_text())
                event = hook_obj["event"]
                self.assertEqual(event["hook_event_name"], "Stop")
                self.assertEqual(event["session_id"], "codex-session")
                self.assertEqual(event["authorization"], "[REDACTED]")
                self.assertEqual(event["last_assistant_message"], "[REDACTED]")

                audit_path = base / "audit" / "event-status.jsonl"
                parsed = parse_log_line("codex", json.dumps(hook_obj))
                self.assertIsNotNone(parsed)
                append_status_audit_record(parsed, None, path=audit_path)

                latest_path = base / "state" / "latest.json"
                monitor = LiveAgentMonitor(latest_state_path=latest_path)
                live_event = parse_log_line(
                    "claude",
                    json.dumps(
                        {
                            "hook_event_name": "PreToolUse",
                            "session_id": "claude-session",
                            "tool_name": "Bash",
                            "logged_at": datetime.now(timezone.utc).isoformat(),
                        }
                    ),
                )
                self.assertIsNotNone(live_event)
                monitor.ingest_record(live_event)

                cache_path = base / "usage" / "usage-cache.json"
                usage_stats.scan_usage(
                    base / "missing-claude-root",
                    cache_path,
                    codex_root=base / "missing-codex-root",
                )
            finally:
                os.umask(previous)

            for directory in (
                settings_path.parent,
                hook_path.parent,
                audit_path.parent,
                latest_path.parent,
                cache_path.parent,
            ):
                self.assertEqual(self._mode(directory), 0o700, directory)
            for path in (
                settings_path,
                hook_path,
                audit_path,
                latest_path,
                cache_path,
            ):
                self.assertEqual(self._mode(path), 0o600, path)

    def test_atomic_state_entrypoints_refuse_preplanted_symlink_targets(self) -> None:
        from sidepulse import usage_stats

        with tempfile.TemporaryDirectory() as tmp:
            base = Path(tmp)
            outside = base / "outside.json"
            outside.write_text("outside stays unchanged")

            settings_link = base / "settings.json"
            settings_link.symlink_to(outside)
            with self.assertRaises(OSError):
                save_settings(AgentMonitorSettings(), settings_link)
            self.assertTrue(settings_link.is_symlink())

            latest_link = base / "latest.json"
            latest_link.symlink_to(outside)
            monitor = LiveAgentMonitor(latest_state_path=latest_link)
            event = parse_log_line(
                "claude",
                json.dumps(
                    {
                        "hook_event_name": "PreToolUse",
                        "session_id": "session",
                        "tool_name": "Bash",
                        "logged_at": datetime.now(timezone.utc).isoformat(),
                    }
                ),
            )
            self.assertIsNotNone(event)
            monitor.ingest_record(event)
            self.assertTrue(latest_link.is_symlink())
            self.assertTrue(monitor._latest_state_dirty)
            self.assertEqual(monitor._latest_state_written_at, 0.0)

            cache_link = base / "usage-cache.json"
            cache_link.symlink_to(outside)
            usage_stats.scan_usage(base / "missing", cache_link)
            self.assertTrue(cache_link.is_symlink())
            self.assertEqual(outside.read_text(), "outside stays unchanged")

