    def test_controller_initializes_exact_registry_scoped_refresh_authority(self) -> None:
        from sidepulse.capacity_refresh import RefreshStatusKind

        source_states = self.controller._capacity_refresh_coordinator.snapshot_state(
            100.0
        ).sources

        self.assertEqual(len(source_states), 2)
        self.assertEqual(
            {row.key.source for row in source_states},
            {self._source("codex"), self._source("claude")},
        )
        # The refresh scope is the pool the capacity policy declares, not a
        # literal. The coordinator rejects any snapshot whose lanes fall
        # outside its key's scope, so a hardcoded "plan" would have thrown
        # away every reading the moment a producer emitted a real lane.
        self.assertEqual(
            {row.key.source.provider_id: row.key.pool for row in source_states},
            {"codex": "codex-chatgpt-plan", "claude": "claude-consumer-plan"},
        )
        # Codex has an account scope now for the same reason Claude does: its
        # producer stamps one on every lane, and the coordinator throws away
        # any snapshot whose lanes do not match the key exactly. It is a
        # constant meaning "the plan currently signed in on this machine",
        # never an account identifier.
        self.assertEqual(
            {
                row.key.source.provider_id: row.key.account_discriminator
                for row in source_states
            },
            {"codex": "codex-chatgpt", "claude": "claude-consumer"},
        )
        self.assertTrue(
            all(row.status is RefreshStatusKind.IDLE for row in source_states)
        )
        self.assertEqual(self.controller._capacity_refresh_deadline_timers, {})

    def test_menu_open_enqueues_exact_source_without_executing_source_work(self) -> None:
        now = time.monotonic()
