class ProviderPinTests(unittest.TestCase):
    """Story #16: a pinned device is one provider's channel -- and asks
    are never partitioned."""

    def setUp(self) -> None:
        isolate_controller(self)

    def _settings_with_device(self):
        return AgentMonitorSettings(
            devices=(
                DeviceDisplaySetting(
                    device_id="Dot", name="SidePulse Dot", path="/Volumes/Dot"
                ),
            )
        )

    def test_pin_round_trips_and_validates(self) -> None:
        settings = self._settings_with_device().with_device_provider_pin("Dot", "codex")
        self.assertEqual(settings.device_provider_pin("Dot"), "codex")
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(settings, path)
            self.assertEqual(load_settings(path).device_provider_pin("Dot"), "codex")
        self.assertIsNone(
            settings.with_device_provider_pin("Dot", None).device_provider_pin("Dot")
        )
        with self.assertRaises(ValueError):
            settings.with_device_provider_pin("Dot", "gemini")

    def test_ask_still_escalates_on_a_pinned_device(self) -> None:
        """The regression the spec demands: an ask from the OTHER
        provider still takes over a pinned device, because escalation
        claims resolve in the display ladder before the agent display
        (and its pin filter) is ever consulted."""
        device = self.status_bar.StatusBarDevice(
            device_id="Dot",
            name="SidePulse Dot",
            root=Path("/Volumes/Dot"),
            target=Path("/Volumes/Dot/LEDS.LED"),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
        )
        self.controller.settings = self._settings_with_device().with_device_provider_pin(
            "Dot", "codex"
        ).with_escalation_tier("takeover")
        self.controller.ask_blocked_since = time.monotonic() - 400.0
        self.assertEqual(
            self.controller.active_led_display_kind_for_device(device, None),
            self.status_bar.LED_DISPLAY_ESCALATION,
        )


class NightWarmthTests(unittest.TestCase):
    """Story #8: 19:00-07:00 warmth composes with calibration gains."""

    def setUp(self) -> None:
        isolate_controller(self)

    def test_off_by_default_and_daytime_identity(self) -> None:
        gains = (1.0, 1.0, 1.0)
        self.assertEqual(self.controller.apply_night_warmth(gains, hour=22), gains)
        self.controller.settings = (
            self.controller.settings.with_night_warmth_enabled(True)
        )
        self.assertEqual(self.controller.apply_night_warmth(gains, hour=12), gains)

    def test_evening_composes_with_calibration(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_night_warmth_enabled(True)
        )
        warmed = self.controller.apply_night_warmth((0.8, 1.0, 0.5), hour=22)
        self.assertAlmostEqual(warmed[0], 0.8)
        self.assertAlmostEqual(warmed[1], 0.87)
        self.assertAlmostEqual(warmed[2], 0.35)
        # The overnight side of the window counts too.
        self.assertNotEqual(
            self.controller.apply_night_warmth((1.0, 1.0, 1.0), hour=3),
            (1.0, 1.0, 1.0),
        )

    def test_window_edges(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_night_warmth_enabled(True)
        )
        self.assertTrue(self.controller.night_warmth_active(hour=19))
        self.assertTrue(self.controller.night_warmth_active(hour=6))
        self.assertFalse(self.controller.night_warmth_active(hour=7))
        self.assertFalse(self.controller.night_warmth_active(hour=18))


class FocusSignalPolicyTests(unittest.TestCase):
    """Story #12: per-Focus signal policies hold courtesy glows."""

    def setUp(self) -> None:
        isolate_controller(self)

    def test_policy_defaults_to_all(self) -> None:
        self.assertEqual(self.controller.active_focus_policy(), "all")
        self.assertFalse(self.controller.courtesy_signals_held())

    def test_strictest_active_policy_wins(self) -> None:
        self.controller.settings = (
            self.controller.settings
            .with_focus_signal_policy("focus-work", "asks_only")
            .with_focus_signal_policy("focus-sleep", "silent")
        )
        self.controller._focus_ids_cache = (float("inf"), ["focus-work"])
        self.assertEqual(self.controller.active_focus_policy(), "asks_only")
        self.assertTrue(self.controller.courtesy_signals_held())
        self.controller._focus_ids_cache = (
            float("inf"),
            ["focus-work", "focus-sleep"],
        )
        self.assertEqual(self.controller.active_focus_policy(), "silent")

    def test_inactive_policy_holds_nothing(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_focus_signal_policy("focus-work", "silent")
        )
        self.controller._focus_ids_cache = (float("inf"), [])
        self.assertEqual(self.controller.active_focus_policy(), "all")
        self.assertFalse(self.controller.courtesy_signals_held())

    def test_quiet_hour_still_holds(self) -> None:
        self.controller.quiet_until_monotonic = time.monotonic() + 60.0
        self.assertTrue(self.controller.courtesy_signals_held())

    def test_policy_holds_quota_blink(self) -> None:
        self.controller.settings = (
            self.controller.settings
            .with_quota_alerts_enabled(True)
            .with_focus_signal_policy("focus-work", "asks_only")
        )
        self.controller._focus_ids_cache = (float("inf"), ["focus-work"])
        self.controller.track_quota_thresholds({"Codex weekly": 70.0})
        self.controller.track_quota_thresholds({"Codex weekly": 95.0})
        self.assertEqual(self.controller.quota_blink_until, 0.0)

    def test_setting_all_removes_the_key(self) -> None:
        settings = AgentMonitorSettings().with_focus_signal_policy("x", "silent")
        self.assertEqual(settings.focus_signal_policy, {"x": "silent"})
        self.assertEqual(
            settings.with_focus_signal_policy("x", "all").focus_signal_policy, {}
        )


class QuotaAlertTests(unittest.TestCase):
    """Quota threshold blinks: edge-triggered, opt-in, quiet-aware."""

    def setUp(self) -> None:
        isolate_controller(self)

    def test_crossings_fire_upward_only_and_never_on_first_sight(self) -> None:
        from sidepulse.signals import quota_crossings

        thresholds = (75.0, 90.0)
        self.assertEqual(quota_crossings({}, {"Codex weekly": 92.0}, thresholds), [])
        self.assertEqual(
            quota_crossings({"Codex weekly": 70.0}, {"Codex weekly": 80.0}, thresholds),
            [("Codex weekly", 75.0)],
        )
        self.assertEqual(
            quota_crossings({"Codex weekly": 80.0}, {"Codex weekly": 85.0}, thresholds),
            [],
        )
        self.assertEqual(
            quota_crossings({"Codex weekly": 60.0}, {"Codex weekly": 95.0}, thresholds),
            [("Codex weekly", 75.0), ("Codex weekly", 90.0)],
        )

    def test_track_quota_thresholds_stays_dormant_when_legacy_enable_is_requested(
        self,
    ) -> None:
        self.controller.settings = (
            self.controller.settings.with_quota_alerts_enabled(True)
        )
        self.assertFalse(self.controller.settings.quota_alerts_enabled)
        self.controller.track_quota_thresholds({"Codex weekly": 70.0})
        self.assertEqual(self.controller.quota_blink_until, 0.0)
        with patch.object(self.controller, "refresh_") as refresh:
            self.controller.track_quota_thresholds({"Codex weekly": 91.0})
        self.assertEqual(self.controller.quota_blink_until, 0.0)
        self.assertIsNone(self.controller.quota_blink_label)
        self.assertIsNone(self.controller.quota_blink_color)
        refresh.assert_not_called()

    def test_disabled_or_quiet_never_blinks(self) -> None:
        self.controller.track_quota_thresholds({"Codex weekly": 70.0})
        self.controller.track_quota_thresholds({"Codex weekly": 95.0})
        self.assertEqual(self.controller.quota_blink_until, 0.0)
        self.controller.settings = (
            self.controller.settings.with_quota_alerts_enabled(True)
        )
        self.controller.quiet_until_monotonic = time.monotonic() + 3600.0
        self.controller.track_quota_thresholds({"Codex weekly": 60.0})
        self.controller.track_quota_thresholds({"Codex weekly": 95.0})
        self.assertEqual(self.controller.quota_blink_until, 0.0)

    def test_quota_sunrise_fires_on_reset_only(self) -> None:
        from sidepulse.signals import quota_resets

        # First sight: silent. High->low: sunrise. Drift down: silent.
        self.assertEqual(quota_resets({}, {"Codex weekly": 2.0}), [])
        self.assertEqual(
            quota_resets({"Codex weekly": 83.0}, {"Codex weekly": 1.0}),
            ["Codex weekly"],
        )
        self.assertEqual(
            quota_resets({"Codex weekly": 40.0}, {"Codex weekly": 5.0}), []
        )

    def test_sunrise_consumer_stays_dormant(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_quota_alerts_enabled(True)
        )
        self.controller.track_quota_thresholds({"Codex weekly": 83.0})
        with patch.object(self.controller, "refresh_") as refresh:
            self.controller.track_quota_thresholds({"Codex weekly": 1.0})
        self.assertIsNone(self.controller.completion_sweep_color)
        self.assertEqual(self.controller.completion_sweep_until, 0.0)
        refresh.assert_not_called()

    def test_threshold_settings_migrate_disabled_and_are_not_resaved(self) -> None:
        from sidepulse.settings import AgentMonitorSettings, load_settings, save_settings

        configured = AgentMonitorSettings().with_quota_alert_thresholds([90, 50.5, 90])
        self.assertEqual(configured.quota_alert_thresholds, (90.0, 95.0))
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured.with_quota_alerts_enabled(True), path)
            loaded = load_settings(path)
            payload = json.loads(path.read_text())
        self.assertFalse(loaded.quota_alerts_enabled)
        self.assertEqual(loaded.quota_alert_thresholds, (90.0, 95.0))
        self.assertNotIn("quota_alerts_enabled", payload)
        self.assertNotIn("quota_alert_thresholds", payload)
        self.assertEqual(
            AgentMonitorSettings().with_quota_alert_thresholds([]).quota_alert_thresholds,
            (90.0, 95.0),
        )


class GlowDialTests(unittest.TestCase):
    """The dimming dials: pitch-black Screen Bar, physical resting glow."""

    def setUp(self) -> None:
        isolate_controller(self)

    def test_resting_glow_replaces_dark_tokens_before_gains(self) -> None:
        from sidepulse.led_status import apply_resting_glow_to_program

        program = "#FF0000 300ms pulse\noff 200ms cosine\n3:#000000 100ms ease\nrepeat"
        glowed = apply_resting_glow_to_program(program, 0.1)
        self.assertNotIn("off ", glowed)
        self.assertNotIn("#000000", glowed)
        self.assertIn("#1A1A1A", glowed)
        # Zero is a strict no-op -- classic full dark.
        self.assertEqual(apply_resting_glow_to_program(program, 0.0), program)

    def test_screen_bar_min_glow_round_trip_and_pitch_black(self) -> None:
        from sidepulse.settings import AgentMonitorSettings, load_settings, save_settings

        configured = AgentMonitorSettings().with_screen_bar_min_glow(0.0)
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured, path)
            self.assertEqual(load_settings(path).screen_bar_min_glow, 0.0)
        self.assertEqual(
            AgentMonitorSettings().with_screen_bar_min_glow(2.0).screen_bar_min_glow,
            1.0,
        )

    def test_pitch_black_floor_lets_bar_go_fully_dark(self) -> None:
        self.controller.settings = self.controller.settings.with_screen_bar_min_glow(0.0)
        device = self.status_bar.StatusBarDevice(
            device_id=self.status_bar.VIRTUAL_DEVICE_ID,
            name="Screen Bar",
            root=Path(self.status_bar.VIRTUAL_DEVICE_ID),
            target=Path(self.status_bar.VIRTUAL_DEVICE_ID),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
            brightness=10,
            auto_brightness_enabled=False,
        )
        # With the dial at zero no floor applies -- tiny stays tiny.
        self.assertLessEqual(
            self.controller.effective_brightness_for_device(device), 10
        )
        self.controller.settings = self.controller.settings.with_screen_bar_min_glow(0.25)
        self.assertGreaterEqual(
            self.controller.effective_brightness_for_device(device), 63
        )

    def test_bracket_floor_zero_means_pitch_black(self) -> None:
        from sidepulse import virtual_device

        view = virtual_device.VirtualLedView.alloc().initWithFrame_(((0, 0), (400.0, 37.0)))
        view.setMinGlow_(0.0)
        dim = [(0.02, 0.01, 0.01, 0.01)] * 8
        rendered = view._bracket_colors(dim)
        self.assertTrue(all(c[3] <= 0.011 for c in rendered))

    def test_screen_bar_resting_glow_reaches_the_program(self) -> None:
        from sidepulse.led_status import apply_resting_glow_to_program

        program = "off 300ms cosine\n#FF0000 200ms pulse\nrepeat"
        rendered = apply_resting_glow_to_program(program, 0.12)
        self.assertNotIn("off ", rendered)

    def test_device_resting_glow_round_trip(self) -> None:
        from sidepulse.settings import AgentMonitorSettings

        settings = AgentMonitorSettings()
        # No devices yet: setter is a safe no-op, getter defaults 0.
        settings = settings.with_device_resting_glow("nope", 0.1)
        self.assertEqual(settings.resting_glow_for_device("nope"), 0.0)


class PaletteTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)

    def test_curated_palettes_are_complete_and_valid(self) -> None:
        from sidepulse.colors import CURATED_PALETTES

        for name, palette in CURATED_PALETTES.items():
            for key in ("working", "done", "ask", "idle"):
                value = palette["modes"][key]
                self.assertRegex(value, r"^#[0-9A-F]{6}$", f"{name}/{key}")
            self.assertEqual(
                set(palette["agents"]), {"claude", "codex", "gemini", "devin"}
            )
            # Working, done and ask must be tellable apart.
            self.assertEqual(
                len({palette["modes"][k] for k in ("working", "done", "ask")}), 3
            )

    def test_oklch_out_of_gamut_desaturates_instead_of_clipping(self) -> None:
        from sidepulse.colors import oklch_hex

        value = oklch_hex(0.5, 5.0, 200.0)
        self.assertRegex(value, r"^#[0-9A-F]{6}$")

    def test_apply_palette_round_trip(self) -> None:
        from types import SimpleNamespace as NS

        from sidepulse.colors import CURATED_PALETTES

        sender = NS(identifier=lambda: "Sunset")
        with patch.object(self.controller, "refresh_") as refresh:
            self.controller.applyPalette_(sender)
        refresh.assert_called_once_with(None)
        expected = CURATED_PALETTES["Sunset"]
        self.assertEqual(
            self.controller.settings.colors.mode_colors["working"],
            expected["modes"]["working"],
        )
        self.assertEqual(
            self.controller.settings.colors.agent_color("gemini"),
            expected["agents"]["gemini"],
        )


class UsageStatsTests(unittest.TestCase):
    """The T3-exact usage pipeline: substring gate, global first-seen
    dedupe, per-file persisted cache, cost + cache-savings math."""

    def _write_transcript(self, root, name, rows):
        path = root / "proj" / f"{name}.jsonl"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("\n".join(json.dumps(row) for row in rows) + "\n")
        return path

    def _assistant_row(self, message_id, *, model="claude-sonnet-5", inp=1000, cached=0, out=500):
        return {
            "type": "assistant",
            "timestamp": "2026-08-11T12:00:00Z",
            "message": {
                "id": message_id,
                "model": model,
                "usage": {
                    "input_tokens": inp,
                    "cache_read_input_tokens": cached,
                    "cache_creation_input_tokens": 0,
                    "output_tokens": out,
                },
            },
        }

    def test_repeated_usage_blocks_count_once(self) -> None:
        from sidepulse import usage_stats

        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            # The same message id appears twice in one file AND again in a
            # forked session file -- T3's ~2.4x overcount bug class.
            self._write_transcript(
                root, "a", [self._assistant_row("msg_1"), self._assistant_row("msg_1")]
            )
            self._write_transcript(root, "b", [self._assistant_row("msg_1")])
            totals = usage_stats.scan_usage(root, None)
            self.assertEqual(totals.input_tokens, 1000)
            self.assertEqual(totals.output_tokens, 500)

    def test_cost_and_cache_savings_math(self) -> None:
        from sidepulse import usage_stats

        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            self._write_transcript(
                root,
                "a",
                [self._assistant_row("msg_1", inp=1_000_000, cached=1_000_000, out=0)],
            )
            totals = usage_stats.scan_usage(root, None)
            # 1M uncached at $3 + 1M cached at $0.30.
            self.assertAlmostEqual(totals.cost_usd, 3.30, places=2)
            # Savings: the cached MTok would have cost $3, paid $0.30.
            self.assertAlmostEqual(totals.cache_savings_usd, 2.70, places=2)

    def test_cache_warm_scan_matches_cold_and_survives_corruption(self) -> None:
        from sidepulse import usage_stats

        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            cache = Path(tmp) / "cache.json"
            self._write_transcript(root, "a", [self._assistant_row("msg_1")])
            cold = usage_stats.scan_usage(root, cache)
            self.assertTrue(cache.exists())
            warm = usage_stats.scan_usage(root, cache)
            self.assertEqual(cold.input_tokens, warm.input_tokens)
            self.assertEqual(cold.sessions, warm.sessions)
            cache.write_text("{corrupt")
            recovered = usage_stats.scan_usage(root, cache)
            self.assertEqual(recovered.input_tokens, cold.input_tokens)

    def test_summary_line_shapes(self) -> None:
        from sidepulse import usage_stats

        empty = usage_stats.UsageTotals()
        self.assertIsNone(usage_stats.usage_summary_line(empty))
        totals = usage_stats.UsageTotals()
        totals.sessions.add("s1")
        totals.input_tokens = 2_000_000
        totals.cost_usd = 1.5
        totals.cache_savings_usd = 4.0
        cost_line = usage_stats.usage_summary_line(totals, "cost")
        self.assertIn("1 session", cost_line)
        self.assertIn("$1.50", cost_line)
        self.assertIn("saved $4.00", cost_line)
        token_line = usage_stats.usage_summary_line(totals, "tokens")
        self.assertIn("2M tokens", token_line)
        self.assertIn("(~$2)", token_line)
        self.assertIn("saved ~$4", token_line)


class T3AdoptionTests(unittest.TestCase):
    """The T3 Code learnings: unseen-done via visit tracking, quiet hour
    with break-through rules, clear-finished, row suffixes."""

    def setUp(self) -> None:
        isolate_controller(self)

    def _status(self, agent_id, mode, *, event="PostToolUse", tool=None):
        return AgentStatus(
            provider="claude",
            agent_id=agent_id,
            display_name=agent_id,
            mode=mode,
            updated_at=datetime.now(timezone.utc),
            event_name=event,
            tool_name=tool,
        )

    def test_hard_vs_soft_ask(self) -> None:
        hard = self._status("claude:session:a", AgentMode.WAITING_FOR_INPUT, event="PermissionRequest")
        soft = self._status("claude:session:b", AgentMode.WAITING_FOR_INPUT, event="Stop")
        error = self._status("claude:session:c", AgentMode.BLOCKED_ERROR, event="PostToolUseFailure")
        self.assertTrue(hard.is_hard_ask)
        self.assertFalse(soft.is_hard_ask)
        self.assertFalse(error.is_hard_ask)

    def test_plan_ready_detection(self) -> None:
        plan = self._status(
            "claude:session:a",
            AgentMode.WAITING_FOR_INPUT,
            event="PermissionRequest",
            tool="ExitPlanMode",
        )
        self.assertTrue(plan.is_plan_ready)
        self.assertIn("Plan ready", self.status_bar.session_row_suffix(plan))

    def test_unseen_completions_cleared_by_menu_open(self) -> None:
        from types import SimpleNamespace as NS

        done = self._status("claude:session:a", AgentMode.COMPLETED, event="Stop")
        snapshot = NS(statuses=[done], stale_statuses=[], collected_at=datetime.now(timezone.utc))
        # Never opened the menu: the completion is unseen.
        self.assertEqual(len(self.status_bar.unseen_completions(snapshot, self.controller)), 1)
        # Opening the menu is the visit that clears it.
        self.controller.menuWillOpen_(None)
        self.assertEqual(self.status_bar.unseen_completions(snapshot, self.controller), [])

    def test_quiet_hour_gates_courtesy_signals_not_asks(self) -> None:
        self.controller.quiet_until_monotonic = time.monotonic() + 3600.0
        self.assertTrue(self.controller.quiet_active())
        device = self.status_bar.StatusBarDevice(
            device_id="SidePulsePro",
            name="SidePulse Pro",
            root=Path("/Volumes/SidePulsePro"),
            target=Path("/Volumes/SidePulsePro/LEDS.LED"),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
        )
        # A live completion sweep would normally claim the display...
        self.controller.completion_sweep_until = time.monotonic() + 30.0
        kind = self.controller.active_led_display_kind_for_device(device, None)
        self.assertNotEqual(kind, self.status_bar.LED_DISPLAY_COMPLETION)
        # ...and does again the moment quiet ends.
        self.controller.quiet_until_monotonic = 0.0
        kind = self.controller.active_led_display_kind_for_device(device, None)
        self.assertEqual(kind, self.status_bar.LED_DISPLAY_COMPLETION)

    def test_clear_finished_hides_rows_until_reactivation(self) -> None:
        from types import SimpleNamespace as NS

        done = self._status("claude:session:a", AgentMode.COMPLETED, event="Stop")
        self.controller.last_snapshot = NS(
            statuses=[done], stale_statuses=[], collected_at=datetime.now(timezone.utc)
        )
        with patch.object(self.controller, "refresh_"):
            self.controller.clearFinished_(None)
        self.assertIn("claude:session:a", self.controller.cleared_session_ids)
        snapshot = self.controller.last_snapshot
        self.assertEqual(self.status_bar.unseen_completions(snapshot, self.controller), [])

    def test_working_suffix_formats_minutes(self) -> None:
        working = self._status("claude:session:a", AgentMode.WORKING)
        suffix = self.status_bar.session_row_suffix(
            working, working_since=time.monotonic() - 250.0
        )
        self.assertIn("4m", suffix)
        with_workers = self.status_bar.session_row_suffix(working, worker_count=3)
        self.assertIn("3 workers", with_workers)


class MenuTeachingTests(unittest.TestCase):
    """The dropdown teaches: empty state says what happens next, and a
    daily tip advertises a feature (clicking it opens the right pane)."""

    def _menu(self, *, hooks_installed: bool = True):
        from sidepulse import status_bar
        from sidepulse.settings import AgentMonitorSettings

        snapshot = SimpleNamespace(
            statuses=[],
            stale_statuses=[],
            collected_at=datetime.now(timezone.utc),
        )
        target = SimpleNamespace(
            settings=AgentMonitorSettings(),
            closed_lid_awake=SimpleNamespace(last_error=None),
            status_bar_devices=list,
            # Pre-seed the hooks probe so the empty state is decided by
            # the TEST, not by whatever hooks the dev machine happens to
            # have installed (the probe reads the real filesystem).
            _menu_hooks_probe=(float("inf"), hooks_installed),
        )
        return status_bar.build_menu(snapshot, status_bar.STATE_IDLE, target)

    def test_empty_state_teaches_the_next_step(self) -> None:
        menu = self._menu()
        mailbox = menu.itemAtIndex_(0)
        recent = next(
            mailbox.submenu().itemAtIndex_(index).submenu()
            for index in range(mailbox.submenu().numberOfItems())
            if mailbox.submenu().itemAtIndex_(index).title() == "Recent"
        )
        titles = [recent.itemAtIndex_(index).title() for index in range(recent.numberOfItems())]
        self.assertIn("No agents yet", titles)
        self.assertTrue(any("Start Claude Code" in title for title in titles))

    def test_empty_state_offers_setup_when_no_hooks_installed(self) -> None:
        menu = self._menu(hooks_installed=False)
        mailbox = menu.itemAtIndex_(0)
        recent = next(
            mailbox.submenu().itemAtIndex_(index).submenu()
            for index in range(mailbox.submenu().numberOfItems())
            if mailbox.submenu().itemAtIndex_(index).title() == "Recent"
        )
        connect = next(
            (
                recent.itemAtIndex_(index)
                for index in range(recent.numberOfItems())
                if "Connect your agents" in recent.itemAtIndex_(index).title()
            ),
            None,
        )
        self.assertIsNotNone(connect)
        self.assertEqual(connect.action(), "openSetup:")
        self.assertFalse(
            any(
                "Start Claude Code" in recent.itemAtIndex_(index).title()
                for index in range(recent.numberOfItems())
            )
        )

    def test_compact_menu_carries_no_tip_rows(self) -> None:
        # The compact root menu deliberately drops the daily tip row; the
        # tip engine itself stays covered by the tests below.
        menu = self._menu()
        tips = [
            menu.itemAtIndex_(index)
            for index in range(menu.numberOfItems())
            if menu.itemAtIndex_(index).title().startswith("Tip: ")
        ]
        self.assertEqual(len(tips), 0)

    def test_every_tip_pane_key_is_a_real_pane(self) -> None:
        from sidepulse import status_bar

        pane_keys = {key for key, _label in status_bar.SETTINGS_SIDEBAR_ITEMS}
        for _text, pane, _anchor in status_bar.DAILY_TIPS:
            if pane is not None:
                self.assertIn(pane, pane_keys)

    def test_dismissed_tips_are_skipped_and_tips_can_turn_off(self) -> None:
        from sidepulse import status_bar
        from sidepulse.settings import AgentMonitorSettings

        settings = AgentMonitorSettings()
        tip = status_bar.daily_tip(settings)
        self.assertIsNotNone(tip)
        settings = settings.with_dismissed_tip(tip[0])
        replacement = status_bar.daily_tip(settings)
        self.assertNotEqual(replacement and replacement[0], tip[0])
        self.assertIsNone(status_bar.daily_tip(settings.with_tips_enabled(False)))

    def test_every_lid_preset_parses_in_the_real_firmware_grammar(self) -> None:
        from sidepulse import status_bar
        from sidepulse.led_wasm import SdLedWasmController

        engine = SdLedWasmController(led_count=8)
        for presets in status_bar.LID_ANIMATION_PRESETS.values():
            for name, duration, program in presets:
                result = engine.parse(program, 0)
                self.assertTrue(
                    result.ok,
                    f"{name}: {result.error_name} at {result.line}:{result.column}",
                )
                self.assertGreater(duration, 0.0)


class StudioDisplayAndTrancheCTests(unittest.TestCase):
    """The review's not-fully-real list: Studio as a persistent display
    choice, weather location override UI, hotplug pane rebuild."""

    def setUp(self) -> None:
        isolate_controller(self)

    def _device(self, display):
        return self.status_bar.StatusBarDevice(
            device_id="SidePulsePro",
            name="SidePulse Pro",
            root=Path("/Volumes/SidePulsePro"),
            target=Path("/Volumes/SidePulsePro/LEDS.LED"),
            connected=True,
            display=display,
        )

    def test_studio_is_a_valid_display_choice(self) -> None:
        from sidepulse.settings import LED_DISPLAY_CHOICES, LED_DISPLAY_STUDIO

        self.assertIn(LED_DISPLAY_STUDIO, LED_DISPLAY_CHOICES)

    def test_studio_display_claims_the_device(self) -> None:
        from sidepulse.settings import LED_DISPLAY_STUDIO

        kind = self.controller.active_led_display_kind_for_device(
            self._device(LED_DISPLAY_STUDIO), None
        )
        self.assertEqual(kind, LED_DISPLAY_STUDIO)

    def test_studio_display_program_validates_and_scales(self) -> None:
        self.controller.settings = self.controller.settings.with_studio_program(
            "#FF0000 500ms pulse\nrepeat"
        )
        program = self.controller.studio_display_program(255)
        self.assertIsNotNone(program)
        self.assertIn("pulse", program)

    def test_broken_studio_program_never_reaches_the_device(self) -> None:
        self.controller.settings = self.controller.settings.with_studio_program(
            "this is not a program !!!"
        )
        self.assertIsNone(self.controller.studio_display_program(255))

    def test_empty_studio_program_falls_back(self) -> None:
        self.assertIsNone(self.controller.studio_display_program(255))

    def test_studio_option_is_in_the_display_popup(self) -> None:
        from sidepulse.settings import LED_DISPLAY_STUDIO

        volume_root = Path(self._tmp.name) / "volumes"
        (volume_root / "SidePulseDot").mkdir(parents=True)
        devices = discover_devices(mount_root=volume_root)
        with patch("sidepulse.status_bar.discover_devices", return_value=devices):
            self.controller.show_settings_window()
            self.controller.ensure_all_settings_panes()
        controls = next(iter(self.controller.device_settings_controls.values()))
        popup = controls["display_popup"]
        keys = {
            popup.itemAtIndex_(index).representedObject()
            for index in range(popup.numberOfItems())
        }
        self.assertIn(LED_DISPLAY_STUDIO, keys)

    def test_apply_weather_location_round_trip(self) -> None:
        self.controller.show_settings_window()
        self.controller.ensure_all_settings_panes()
        lat = self.controller.settings_fields["weather_latitude_field"]
        lon = self.controller.settings_fields["weather_longitude_field"]
        lat.setStringValue_("41.88")
        lon.setStringValue_("-87.63")
        with patch.object(self.controller, "refresh_") as refresh:
            self.controller.applyWeatherLocation_(None)
            self.assertEqual(self.controller.settings.weather_latitude, 41.88)
            self.assertEqual(self.controller.settings.weather_longitude, -87.63)
            lat.setStringValue_("")
            lon.setStringValue_("")
            self.controller.applyWeatherLocation_(None)
        self.assertEqual(refresh.call_args_list, [call(None), call(None)])
        self.assertIsNone(self.controller.settings.weather_latitude)
        self.assertIsNone(self.controller.settings.weather_longitude)

    def test_half_filled_weather_location_is_rejected(self) -> None:
        self.controller.show_settings_window()
        self.controller.ensure_all_settings_panes()
        lat = self.controller.settings_fields["weather_latitude_field"]
        lat.setStringValue_("41.88")
        self.controller.applyWeatherLocation_(None)
        self.assertIsNone(self.controller.settings.weather_latitude)

    def test_devices_pane_rebuilds_on_hotplug_while_visible(self) -> None:
        self.controller.show_settings_window()
        self.controller.ensure_all_settings_panes()
        self.assertEqual(len(self.controller.device_settings_controls), 0)
        # Prime the connection signature, then "plug in" a device.
        self.controller.observe_connected_devices()
        volume_root = Path(self._tmp.name) / "hotplug"
        (volume_root / "SidePulsePro").mkdir(parents=True)
        devices = discover_devices(mount_root=volume_root)
        with patch("sidepulse.status_bar.discover_devices", return_value=devices):
            self.controller.poll_devices_once()
        # Device ids for non-/Volumes roots carry the full path.
        self.assertTrue(
            any(
                "SidePulsePro" in device_id
                for device_id in self.controller.device_settings_controls
            ),
            self.controller.device_settings_controls,
        )


class CalendarAlertTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)

    def _device(self):
        return self.status_bar.StatusBarDevice(
            device_id="SidePulsePro",
            name="SidePulse Pro",
            root=Path("/Volumes/SidePulsePro"),
            target=Path("/Volumes/SidePulsePro/LEDS.LED"),
            connected=True,
            display=self.status_bar.LED_DISPLAY_AGENT,
        )

    def test_settings_round_trip(self) -> None:
        configured = (
            AgentMonitorSettings()
            .with_calendar_alerts_enabled(True)
            .with_calendar_lead_minutes(12.0)
        )
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured, path)
            reloaded = load_settings(path)
        self.assertTrue(reloaded.calendar_alerts_enabled)
        self.assertEqual(reloaded.calendar_lead_minutes, 12.0)
        # Clamps stay sane.
        self.assertEqual(
            AgentMonitorSettings().with_calendar_lead_minutes(500.0).calendar_lead_minutes,
            60.0,
        )

    def test_glow_program_fits_device_limits_and_repeats(self) -> None:
        from sidepulse.device_writer import MAX_LED_BYTES, MAX_LED_LINES
        from sidepulse.led_status import calendar_glow_program

        program = calendar_glow_program(128)
        self.assertLessEqual(len(program.encode()), MAX_LED_BYTES)
        self.assertLessEqual(len(program.splitlines()), MAX_LED_LINES)
        # Unlike a one-shot alert, the warning holds until the event
        # starts -- it must loop.
        self.assertIn("repeat", program)

    def test_display_kind_precedence(self) -> None:
        device = self._device()
        self.controller.settings = (
            self.controller.settings.with_calendar_alerts_enabled(True)
            .with_reminder_alerts_enabled(True)
        )
        # Glow active -> calendar outranks the agent display.
        self.controller.calendar_glow_until = time.monotonic() + 120.0
        self.assertEqual(
            self.controller.active_led_display_kind_for_device(device, None),
            self.status_bar.LED_DISPLAY_CALENDAR,
        )
        # A due reminder is a moment: it outranks the calendar's state.
        self.controller.reminders_glow_until = time.monotonic() + 2.0
        self.assertEqual(
            self.controller.active_led_display_kind_for_device(device, None),
            self.status_bar.LED_DISPLAY_REMINDERS,
        )
        # All expired -> back to agent status.
        self.controller.reminders_glow_until = 0.0
        self.controller.calendar_glow_until = time.monotonic() - 1.0
        self.assertEqual(
            self.controller.active_led_display_kind_for_device(device, None),
            self.status_bar.LED_DISPLAY_AGENT,
        )

    def test_reminders_due_glows_once_per_reminder(self) -> None:
        self.controller.settings = self.controller.settings.with_reminder_alerts_enabled(True)
        with patch.object(self.controller, "refresh_") as refresh:
            self.controller._apply_reminders_observation_result(
                self.status_bar.RemindersObservationResult(True, ("1" * 64,))
            )
            self.assertGreater(self.controller.reminders_glow_until, time.monotonic())
            first_until = self.controller.reminders_glow_until
            # The same reminder arriving again (still due, still incomplete)
            # must NOT re-fire the glow.
            self.controller.reminders_glow_until = 0.0
            self.controller._apply_reminders_observation_result(
                self.status_bar.RemindersObservationResult(True, ("1" * 64,))
            )
            self.assertEqual(self.controller.reminders_glow_until, 0.0)
            # A different reminder fires fresh.
            self.controller._apply_reminders_observation_result(
                self.status_bar.RemindersObservationResult(True, ("2" * 64,))
            )
        self.assertEqual(refresh.call_args_list, [call(None), call(None)])
        self.assertGreater(self.controller.reminders_glow_until, 0.0)
        self.assertGreaterEqual(first_until, 0.0)

    def test_reminder_settings_round_trip(self) -> None:
        configured = AgentMonitorSettings().with_reminder_alerts_enabled(True)
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "settings.json"
            save_settings(configured, path)
            reloaded = load_settings(path)
        self.assertTrue(reloaded.reminder_alerts_enabled)


class ReminderObservationRuntimeTests(unittest.TestCase):
    def setUp(self) -> None:
        isolate_controller(self)
        self.clock = [675.0]
        self.factory = _PresentationTimerFactory()
        self.controller._presentation_monotonic = lambda: self.clock[0]
        self.controller._runtime_timer_registry = (
            self.controller._build_presentation_timer_registry(
                timer_factory=self.factory,
                monotonic=lambda: self.clock[0],
            )
        )
        self.controller._presentation_scheduler_state = (
            self.status_bar.PresentationSchedulerState()
        )
        self.controller._presentation_scheduler_inputs = None
        self.controller._runtime_started = True
        self.controller.leds_enabled = False
        self.controller._runtime_worker_monotonic = lambda: self.clock[0]

    def tearDown(self) -> None:
        self.controller._runtime_worker_registry.close_all(timeout_seconds=1.0)

    def _inputs(self, **changes):
        values = {
            "screen_bar_enabled": False,
            "visible": False,
            "display_asleep": False,
            "app_terminating": False,
            "animation_active": False,
            "next_visual_change_at": None,
            "alcove_enabled": False,
            "alcove_relevant": False,
            "pointer_interaction_relevant": False,
        }
        values.update(changes)
        return self.status_bar.PresentationSchedulerInputs(**values)

    def test_reminder_intent_is_disabled_by_default_and_withdrawn_immediately(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_reminder_alerts_enabled(False)
        )
        with (
            patch.object(self.status_bar.reminders_watch, "fetch_due") as fetch_due,
            patch.object(
                self.status_bar.reminders_watch,
                "request_access",
            ) as request_access,
        ):
            self.controller.reconcile_presentation_timers(self._inputs())
            self.controller._reminders_observation_timer_fired()

            self.assertNotIn(
                self.status_bar.RuntimeFeature.REMINDERS_OBSERVATION,
                self.controller._runtime_timer_registry.snapshot().active_features,
            )
            self.assertEqual(self.controller._os_poll_worker.snapshot().submitted, 0)
            fetch_due.assert_not_called()
            request_access.assert_not_called()

            self.controller.settings = (
                self.controller.settings.with_reminder_alerts_enabled(True)
            )
            for _ in range(100):
                self.controller.reconcile_presentation_timers(self._inputs())

            reminder_timers = tuple(
                timer
                for timer in self.factory.live
                if timer.feature
                is self.status_bar.RuntimeFeature.REMINDERS_OBSERVATION
            )
            self.assertEqual(len(reminder_timers), 1)
            self.assertEqual(reminder_timers[0].delay, 60.0)
            self.assertEqual(reminder_timers[0].interval, 60.0)
            self.assertEqual(reminder_timers[0].tolerances, [6.0])

            self.controller.settings = (
                self.controller.settings.with_reminder_alerts_enabled(False)
            )
            self.controller.reconcile_presentation_timers(self._inputs())

        self.assertEqual(reminder_timers[0].invalidations, 1)
        self.assertNotIn(
            self.status_bar.RuntimeFeature.REMINDERS_OBSERVATION,
            self.controller._runtime_timer_registry.snapshot().active_features,
        )

    def test_reminder_tick_uses_bounded_private_os_poll_adapter(self) -> None:
        submissions = []
        self.controller.settings = (
            self.controller.settings.with_reminder_alerts_enabled(True)
        )
        self.controller._reminders_observation_active = True
        self.controller._os_poll_generation = 8
        self.controller._presentation_scheduler_inputs = self._inputs()
        self.controller._os_poll_worker = SimpleNamespace(submit=submissions.append)

        self.controller._reminders_observation_timer_fired()

        self.assertEqual(len(submissions), 1)
        command = submissions[0]
        self.assertIs(command.domain, self.status_bar.RuntimeWorkerDomain.OS_POLL)
        self.assertEqual(command.key, "reminders-observation")
        self.assertEqual(command.generation, 8)
        self.assertEqual(
            command.payload,
            self.status_bar.RemindersObservationRequest(lookback_seconds=120.0),
        )
        self.assertNotIn("title", repr(command.payload).casefold())
        self.assertNotIn("identifier", repr(command.payload).casefold())

        private_identifier = "private-reminder-id"
        private_title = "Prepare confidential Project Atlas memo"
        with patch.object(
            self.status_bar.reminders_watch,
            "fetch_due",
            side_effect=lambda _lookback, completion: completion(
                [(private_identifier, private_title)]
            ),
        ):
            result = self.controller._execute_os_poll_command(command)

        self.assertIsInstance(result, self.status_bar.RemindersObservationResult)
        self.assertTrue(result.available)
        self.assertEqual(len(result.identifiers), 1)
        self.assertEqual(len(result.identifiers[0]), 64)
        self.assertNotIn(private_identifier, repr(result))
        self.assertNotIn(private_title, repr(result))
        self.assertNotIn("title", repr(result).casefold())

    def test_reminder_results_are_fenced_bounded_and_use_exact_cue_deadline(self) -> None:
        self.controller.settings = (
            self.controller.settings.with_reminder_alerts_enabled(True)
        )
        self.controller._reminders_observation_active = True
        self.controller._reminders_observation_fire_at = self.clock[0] + 60.0
        self.controller._os_poll_generation = 11
        self.controller._presentation_scheduler_inputs = self._inputs()
        self.controller.refresh_ = MagicMock()
        request = self.status_bar.RemindersObservationRequest(
            lookback_seconds=120.0
        )

        def command(generation: int, deadline: float):
            return self.status_bar.RuntimeWorkCommand(
                self.status_bar.RuntimeWorkerDomain.OS_POLL,
                "reminders-observation",
                generation,
                deadline,
                request,
            )

        result = self.status_bar.RemindersObservationResult(True, ("a" * 64,))
        self.controller._apply_os_poll_result(
            command(10, self.clock[0] + 30.0),
            result,
        )
        self.controller._apply_os_poll_result(
            command(11, self.clock[0] - 1.0),
            result,
        )
        self.assertEqual(self.controller.reminders_glow_until, 0.0)
        self.controller.refresh_.assert_not_called()

        current = command(11, self.clock[0] + 30.0)
        self.controller._apply_os_poll_result(current, result)
        first_deadline = self.controller.reminders_glow_until
        self.assertGreater(first_deadline, self.clock[0])
        cue_timer = next(
            timer
            for timer in self.factory.live
            if timer.feature is self.status_bar.RuntimeFeature.TEST_SIGNAL_DEADLINE
        )
        self.assertAlmostEqual(cue_timer.delay, first_deadline - self.clock[0])
        self.assertIsNone(cue_timer.interval)
        self.assertEqual(cue_timer.tolerances, [0.0])
        self.controller.refresh_.assert_called_once_with(None)

        self.controller._apply_os_poll_result(current, result)
        self.assertEqual(self.controller.reminders_glow_until, first_deadline)
        self.assertIs(
            next(
                timer
                for timer in self.factory.live
                if timer.feature
                is self.status_bar.RuntimeFeature.TEST_SIGNAL_DEADLINE
            ),
            cue_timer,
        )
        self.controller.refresh_.assert_called_once_with(None)

        second_batch = tuple(
            f"{index:064x}" for index in range(1, 257)
        )
        self.controller._apply_os_poll_result(
            current,
            self.status_bar.RemindersObservationResult(True, second_batch),
        )
        self.assertLessEqual(
            len(self.controller.reminders_seen),
            self.status_bar.MAX_REMINDER_OBSERVATION_IDENTIFIERS,
        )

        self.controller._presentation_scheduler_inputs = self._inputs(
            display_asleep=True
        )
        self.controller._apply_os_poll_result(
            current,
            self.status_bar.RemindersObservationResult(True, ("b" * 64,)),
        )
        self.controller._presentation_scheduler_inputs = self._inputs(
            app_terminating=True
        )
        self.controller._apply_os_poll_result(
            current,
            self.status_bar.RemindersObservationResult(True, ("c" * 64,)),
        )
        self.assertNotIn("b" * 64, self.controller.reminders_seen)
        self.assertNotIn("c" * 64, self.controller.reminders_seen)

    def test_reminder_callback_timeout_releases_shared_worker_and_late_callback_is_inert(self) -> None:
        started = threading.Event()
        late_callbacks = []
        drains = []

        def fetch_due(_lookback, completion):
            late_callbacks.append(completion)
            started.set()

        self.controller._runtime_worker_registry.close_all(timeout_seconds=1.0)
        (
            self.controller._runtime_worker_registry,
            self.controller._os_poll_worker,
        ) = self.controller._build_runtime_worker_registry(
            monotonic=lambda: self.clock[0],
            dispatch_main=drains.append,
        )
        self.controller.settings = (
            self.controller.settings.with_reminder_alerts_enabled(True)
        )
        self.controller._reminders_observation_active = True
        self.controller._reminders_observation_fire_at = self.clock[0] + 60.0
        self.controller._lid_observation_active = True
        self.controller._os_poll_generation = 17
        self.controller._presentation_scheduler_inputs = self._inputs()

        with (
            patch.object(
                self.status_bar,
                "REMINDERS_FETCH_TIMEOUT_SECONDS",
                0.01,
            ),
            patch.object(
                self.status_bar.reminders_watch,
                "fetch_due",
                side_effect=fetch_due,
            ),
            patch.object(self.status_bar, "read_lid_closed", return_value=True),
        ):
            self.controller._reminders_observation_timer_fired()
            self.assertTrue(started.wait(1.0))
            self.controller._lid_observation_timer_fired()
            deadline = time.monotonic() + 1.0
            while self.controller._os_poll_worker.snapshot().completed < 2:
                if time.monotonic() >= deadline:
                    self.fail("reminder timeout stranded the shared OS worker")
                time.sleep(0.001)

        self.assertEqual(len(drains), 1)
        drains.pop()()
        self.assertTrue(self.controller.last_lid_closed)
        self.assertEqual(self.controller.reminders_glow_until, 0.0)
        self.assertEqual(
            self.controller.reminders_watch_retry_at,
            self.clock[0] + self.status_bar.REMINDERS_WATCH_RETRY_SECONDS,
        )

        previous_seen = dict(self.controller.reminders_seen)
        self.controller._os_poll_generation += 1
        late_callbacks[0]([("late-private-id", "Late private title")])

        self.assertEqual(self.controller.reminders_seen, previous_seen)
        self.assertEqual(self.controller.reminders_glow_until, 0.0)

    def test_reminder_permission_is_explicit_enable_only_main_thread_and_single_flight(self) -> None:
        inputs = self._inputs()
        self.controller.virtual_status_device = SimpleNamespace(
            presentation_scheduler_inputs=lambda: inputs
        )
        worker = MagicMock()
        self.controller._os_poll_worker = worker
        enabled_sender = SimpleNamespace(state=lambda: 1)
        disabled_sender = SimpleNamespace(state=lambda: 0)
        callbacks = []
        request_threads = []

        def request_access(completion):
            callbacks.append(completion)
            request_threads.append(threading.get_ident())

        with (
            patch.object(self.status_bar, "save_settings"),
            patch.object(
                self.status_bar.reminders_watch,
                "authorization_status",
                return_value=self.status_bar.reminders_watch.AUTH_NOT_DETERMINED,
            ) as authorization_status,
            patch.object(
                self.status_bar.reminders_watch,
                "request_access",
                side_effect=request_access,
            ) as request_access_mock,
            patch.object(
                self.status_bar.reminders_watch,
                "fetch_due",
            ) as fetch_due,
        ):
            for _ in range(100):
                self.controller.reconcile_presentation_timers(inputs)
            authorization_status.assert_not_called()
            request_access_mock.assert_not_called()

            self.controller.toggleReminderAlerts_(enabled_sender)
            self.controller.toggleReminderAlerts_(enabled_sender)
            for _ in range(100):
                self.controller.reconcile_presentation_timers(inputs)

            authorization_status.assert_called_once_with()
            request_access_mock.assert_called_once_with(callbacks[0])
            self.assertEqual(request_threads, [threading.main_thread().ident])
            fetch_due.assert_not_called()

            self.controller.toggleReminderAlerts_(disabled_sender)
            callback_thread = threading.Thread(target=lambda: callbacks[0](True))
            callback_thread.start()
            callback_thread.join(1.0)

        self.assertFalse(self.controller._reminders_observation_active)
        self.assertEqual(self.controller.reminders_glow_until, 0.0)
        worker.submit.assert_not_called()

